-- V216: Fix outbound connector config_schema and parameter_groups field mismatches
-- Applied: 2026-08-29
--
-- The pipeline builder UI (public/js/pipeline/components/ConnectorConfigBuilder.js)
-- renders its config form entirely from connectivity_types.config_schema/parameter_groups
-- and saves whatever field names that schema declares, with zero translation before
-- the value reaches the Go connector's Initialize(). For 8 outbound connectors, the
-- schema's field names/types/enum values had drifted from what the Go code actually
-- reads (services/connectors/*.go), so a connector configured through the real UI
-- would silently misconfigure — confirmed empirically, same bug class already fixed
-- once before for http_outbound in V55__Fix_HTTP_Outbound_Config_Schema.sql.
--
-- Verified via a full audit of every real outbound connector against the live
-- database, and confirmed zero real usage exists for any of these 8 type_names in
-- transformation_steps (only file_writer/http_outbound/http_fhir_outbound have real
-- saved rows, none of which are touched here) — this is a pure alignment fix with
-- no existing data at risk.
--
-- ============================================================
-- Outbound connector config_schema + parameter_groups corrections
-- ============================================================

UPDATE connectivity_types
SET config_schema = '{"type":"object","required":["host","port","database","table_name"],"properties":{"host":{"type":"string","title":"Database Host","default":"localhost"},"port":{"type":"integer","title":"Database Port","default":5432,"maximum":65535,"minimum":1},"table_name":{"type":"string","title":"Target Table"},"database":{"type":"string","title":"Database Name"},"password":{"type":"string","title":"Password","format":"password"},"ssl_mode":{"enum":["disable","require","verify-ca","verify-full"],"type":"string","title":"SSL Mode","default":"disable"},"username":{"type":"string","title":"Username"},"write_mode":{"enum":["insert","upsert","update"],"type":"string","title":"Operation","default":"insert"},"batch_size":{"type":"integer","title":"Batch Size","default":1,"maximum":1000,"minimum":1},"unique_key":{"type":"string","title":"Unique Key Columns","description":"Comma-separated column name(s) for UPSERT/UPDATE operations"},"max_open_conns":{"type":"integer","title":"Max Open Connections","default":5,"maximum":50,"minimum":1}}}'::jsonb,
    parameter_groups = '{"basic":["host","port","database","username","password","table_name"],"advanced":["ssl_mode","max_open_conns"],"operation":["write_mode","unique_key","batch_size"]}'::jsonb
WHERE type_name = 'postgresql_outbound';

UPDATE connectivity_types
SET config_schema = '{"type":"object","required":["host","port","database","table_name"],"properties":{"host":{"type":"string","title":"Database Host","default":"localhost"},"port":{"type":"integer","title":"Database Port","default":3306},"table_name":{"type":"string","title":"Target Table"},"database":{"type":"string","title":"Database Name"},"password":{"type":"string","title":"Password","format":"password"},"username":{"type":"string","title":"Username"},"write_mode":{"enum":["insert","upsert","update"],"type":"string","title":"Operation","default":"insert"},"batch_size":{"type":"integer","title":"Batch Size","default":1},"ssl_mode":{"type":"string","title":"SSL Mode","enum":["disable","require","verify-ca","verify-full"],"default":"disable"},"unique_key":{"type":"string","title":"Unique Key Columns","description":"Comma-separated column name(s) for UPSERT/UPDATE operations"}}}'::jsonb,
    parameter_groups = '{"basic":["host","port","database","username","password","table_name"],"advanced":["ssl_mode"],"operation":["write_mode","unique_key","batch_size"]}'::jsonb
WHERE type_name = 'mysql_outbound';

UPDATE connectivity_types
SET config_schema = '{"type":"object","required":["host","port","database","table_name"],"properties":{"host":{"type":"string","title":"Database Host","default":"localhost"},"port":{"type":"integer","title":"Database Port","default":1521},"table_name":{"type":"string","title":"Target Table"},"password":{"type":"string","title":"Password","format":"password"},"username":{"type":"string","title":"Username"},"write_mode":{"enum":["insert","upsert","update"],"type":"string","title":"Operation","default":"insert"},"batch_size":{"type":"integer","title":"Batch Size","default":1},"ssl_mode":{"type":"string","title":"SSL Mode","enum":["disable","require"],"default":"disable","description":"Only \"require\" is currently supported by the connector"},"database":{"type":"string","title":"Service Name","description":"Oracle service name (used as the connect-string SERVICE_NAME)"},"unique_key":{"type":"string","title":"Unique Key Columns","description":"Comma-separated column name(s) for UPSERT/UPDATE operations"}}}'::jsonb,
    parameter_groups = '{"basic":["host","port","database","username","password","table_name"],"advanced":["ssl_mode"],"operation":["write_mode","unique_key","batch_size"]}'::jsonb
WHERE type_name = 'oracle_outbound';

UPDATE connectivity_types
SET config_schema = '{"type":"object","required":["host","port","database","table_name"],"properties":{"host":{"type":"string","title":"Database Host","default":"localhost"},"port":{"type":"integer","title":"Database Port","default":1433},"table_name":{"type":"string","title":"Target Table"},"database":{"type":"string","title":"Database Name"},"password":{"type":"string","title":"Password","format":"password"},"username":{"type":"string","title":"Username"},"write_mode":{"enum":["insert","upsert","update"],"type":"string","title":"Operation","default":"insert"},"batch_size":{"type":"integer","title":"Batch Size","default":1},"ssl_mode":{"type":"string","title":"SSL Mode","enum":["disable","require","verify-full"],"default":"require"},"unique_key":{"type":"string","title":"Unique Key Columns","description":"Comma-separated column name(s) for UPSERT/UPDATE operations"},"authentication_type":{"enum":["sql_authentication","windows_authentication"],"type":"string","title":"Authentication Type","default":"sql_authentication"}}}'::jsonb,
    parameter_groups = '{"basic":["host","port","database","username","password","table_name"],"security":["authentication_type","ssl_mode"],"operation":["write_mode","unique_key","batch_size"]}'::jsonb
WHERE type_name = 'sqlserver_outbound';

UPDATE connectivity_types
SET config_schema = '{"type":"object","required":["uri","database","collection"],"properties":{"database":{"type":"string","title":"Database Name"},"write_mode":{"enum":["insert","upsert"],"type":"string","title":"Operation","default":"insert"},"batch_size":{"type":"integer","title":"Batch Size","default":1,"maximum":1000,"minimum":1},"collection":{"type":"string","title":"Collection Name"},"write_concern":{"enum":["majority","1","2","3"],"type":"string","title":"Write Concern","default":"majority"},"uri":{"type":"string","title":"MongoDB Connection URI","default":"mongodb://localhost:27017","description":"mongodb://user:password@host:port or mongodb+srv://..."},"upsert_field":{"type":"string","title":"Upsert Match Field","description":"Field used to match existing documents for upsert","default":"_id"},"max_pool_size":{"type":"integer","title":"Max Pool Size","default":5}}}'::jsonb,
    parameter_groups = '{"basic":["uri","database","collection"],"advanced":["write_concern","max_pool_size"],"operation":["write_mode","upsert_field","batch_size"]}'::jsonb
WHERE type_name = 'mongodb_outbound';

UPDATE connectivity_types
SET config_schema = '{"type":"object","required":["bucket","region"],"properties":{"prefix":{"type":"string","title":"Object Prefix/Folder"},"region":{"type":"string","title":"AWS Region","default":"us-east-1"},"bucket":{"type":"string","title":"S3 Bucket Name"},"access_key_id":{"type":"string","title":"Access Key ID"},"storage_class":{"enum":["STANDARD","INTELLIGENT_TIERING","STANDARD_IA"],"type":"string","title":"Storage Class","default":"STANDARD"},"key_pattern":{"type":"string","title":"Filename Pattern","default":"{message_id}_{timestamp}.json"},"secret_access_key":{"type":"string","title":"Secret Access Key","format":"password"},"authentication_method":{"enum":["access_keys","iam_role"],"type":"string","title":"Auth Method","default":"access_keys"},"server_side_encryption":{"type":"string","title":"Server-Side Encryption","enum":["AES256","aws:kms","none"],"default":"AES256"},"kms_key_id":{"type":"string","title":"KMS Key ID/ARN","description":"Required when Server-Side Encryption is \"aws:kms\""}}}'::jsonb,
    parameter_groups = '{"basic":["bucket","region","prefix","key_pattern"],"advanced":["storage_class","server_side_encryption","kms_key_id"],"authentication":["authentication_method","access_key_id","secret_access_key"]}'::jsonb
WHERE type_name = 'aws_s3_outbound';

UPDATE connectivity_types
SET config_schema = '{"type":"object","required":["brokers","topic"],"properties":{"required_acks":{"enum":["none","leader","all"],"type":"string","title":"Acknowledgments","default":"all"},"topic":{"type":"string","title":"Topic Name"},"client_id":{"type":"string","title":"Client ID"},"linger_ms":{"type":"integer","title":"Linger Time (ms)","default":0},"batch_size":{"type":"integer","title":"Batch Size (bytes)","default":16384},"sasl_password":{"type":"string","title":"SASL Password","format":"password"},"sasl_username":{"type":"string","title":"SASL Username"},"sasl_mechanism":{"enum":["PLAIN","SCRAM-SHA-256","SCRAM-SHA-512"],"type":"string","title":"SASL Mechanism"},"compression":{"enum":["none","gzip","snappy","lz4","zstd"],"type":"string","title":"Compression Type","default":"none"},"brokers":{"type":"string","title":"Bootstrap Servers","default":"localhost:9092","description":"Comma-separated list"},"message_key_field":{"type":"string","title":"Message Key Field","description":"JSON field in the message to use as the Kafka partition key (e.g. patient_id) — messages with the same key land on the same partition, preserving order"},"sasl_enabled":{"type":"boolean","title":"Enable SASL Authentication","default":false,"description":"Must be enabled for sasl_mechanism/sasl_username/sasl_password to take effect"},"tls_enabled":{"type":"boolean","title":"Enable TLS","default":false},"max_in_flight_requests":{"type":"integer","title":"Max In-Flight Requests","default":5}}}'::jsonb,
    parameter_groups = '{"basic":["brokers","topic","client_id","message_key_field"],"producer":["required_acks","compression","batch_size","linger_ms","max_in_flight_requests"],"security":["sasl_enabled","tls_enabled","sasl_mechanism","sasl_username","sasl_password"]}'::jsonb
WHERE type_name = 'kafka_outbound';

UPDATE connectivity_types
SET config_schema = '{"type":"object","required":["host","port"],"properties":{"host":{"type":"string","title":"Destination Host","description":"Hostname or IP of downstream HL7 system"},"port":{"type":"integer","title":"Destination Port","default":2575,"maximum":65535,"minimum":1024},"password":{"type":"string","title":"Password","format":"password","description":"For basic authentication"},"username":{"type":"string","title":"Username","description":"For basic authentication (placed in MSH-8)"},"source_ip":{"type":"string","title":"Source IP (optional)","description":"Bind to specific local IP address"},"auth_token":{"type":"string","title":"Authentication Token","format":"password","description":"Custom authentication token"},"enable_tls":{"type":"boolean","title":"Enable TLS/SSL","default":false,"description":"Use TLS for encrypted MLLP connection"},"keep_alive":{"type":"boolean","title":"Keep Connection Alive","default":true,"description":"Maintain persistent connection for multiple messages"},"tls_version":{"enum":["TLS_1_2","TLS_1_3"],"type":"string","title":"TLS Version","default":"TLS_1_2"},"ack_timeout_seconds":{"type":"integer","title":"ACK Timeout (seconds)","default":30,"maximum":300,"minimum":5,"description":"Timeout waiting for acknowledgment (ACK/NACK)"},"key_file":{"type":"string","title":"TLS Private Key Path"},"expect_ack":{"type":"boolean","title":"Expect ACK/NACK Response","default":true,"description":"Parse and validate acknowledgment messages"},"certificate_file":{"type":"string","title":"TLS Certificate Path","description":"Client certificate for mutual TLS authentication"},"max_retries":{"type":"integer","title":"Retry Attempts","default":3,"maximum":10,"minimum":0,"description":"Number of retries on connection failure"},"mllp_end_byte_1":{"type":"string","title":"MLLP End Byte 1 (hex)","default":"0x1C","description":"File Separator (FS)"},"mllp_end_byte_2":{"type":"string","title":"MLLP End Byte 2 (hex)","default":"0x0D","description":"Carriage Return (CR)"},"mllp_start_byte":{"type":"string","title":"MLLP Start Byte (hex)","default":"0x0B","description":"Vertical Tab (VT)"},"log_hl7_messages":{"type":"boolean","title":"Log HL7 Messages","default":false,"description":"Log full HL7 message content for debugging"},"message_encoding":{"enum":["UTF-8","ASCII","ISO-8859-1"],"type":"string","title":"Message Encoding","default":"UTF-8"},"use_mllp_framing":{"type":"boolean","title":"Use MLLP Framing","default":true,"description":"Wrap messages with MLLP start/end bytes (0x0B/0x1C/0x0D)"},"connect_timeout_seconds":{"type":"integer","title":"Connection Timeout (seconds)","default":30,"maximum":300,"minimum":5},"write_timeout_seconds":{"type":"integer","title":"Write Timeout (seconds)","default":30,"minimum":5,"maximum":300},"keep_alive_timeout":{"type":"integer","title":"Keep-Alive Timeout (seconds)","default":300,"description":"Close idle connection after timeout"},"verify_server_cert":{"type":"boolean","title":"Verify Server Certificate","default":true},"authentication_type":{"enum":["none","basic","token","mtls"],"type":"string","title":"Authentication Type","default":"none","description":"Authentication method (basic=MSH-8, token=custom, mtls=certificate)"},"retry_delay_ms":{"type":"integer","title":"Retry Delay (ms)","default":3000,"maximum":60000,"minimum":100},"connection_pool_size":{"type":"integer","title":"Connection Pool Size","default":1,"maximum":10,"minimum":1,"description":"Number of concurrent connections to maintain"}}}'::jsonb,
    parameter_groups = '{"basic":["host","port","connect_timeout_seconds","ack_timeout_seconds","write_timeout_seconds"],"advanced":["log_hl7_messages","source_ip"],"protocol":["use_mllp_framing","mllp_start_byte","mllp_end_byte_1","mllp_end_byte_2","message_encoding"],"security":["enable_tls","tls_version","certificate_file","key_file","verify_server_cert"],"connection":["keep_alive","keep_alive_timeout","connection_pool_size"],"reliability":["max_retries","retry_delay_ms","expect_ack"],"authentication":["authentication_type","username","password","auth_token"]}'::jsonb
WHERE type_name = 'tcp_mllp_outbound';

